/**
 * @distilled.cloud/supabase — Supabase Management API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model in
 * `.generated-specs`. Everything else in this folder is hand-written.
 *
 * The hand-written modules are re-exported by NAME (not `export *`): the
 * generated service module star-exported below also exports error classes
 * (`BadRequest`, `NotFound`, …) and shape schemas, and two star exports of
 * the same name silently drop it from the surface. Explicit named exports
 * take precedence, keeping the v0-compatible surface (core error classes at
 * the root) while the service-local generated classes stay reachable via the
 * `./Operations` subpath.
 *
 * @example
 * ```ts
 * import * as Supabase from "@distilled.cloud/supabase";
 * ```
 */
export {
  DEFAULT_API_BASE_URL,
  type Config,
  Credentials,
  CredentialsFromEnv,
  credentials,
  formatHeaders,
} from "./credentials.ts";
export {
  BadGateway,
  BadRequest,
  Conflict,
  ConfigError,
  Forbidden,
  GatewayTimeout,
  InternalServerError,
  Locked,
  NotFound,
  ServiceUnavailable,
  TooManyRequests,
  Unauthorized,
  UnprocessableEntity,
  HTTP_STATUS_MAP,
  DEFAULT_ERRORS,
  API_ERRORS,
  UnknownSupabaseError,
  FreeProjectLimitReached,
  SupabaseParseError,
  type ClientErrors,
  type DefaultErrors,
} from "./errors.ts";
export * as T from "./traits.ts";
export {
  SupabaseProtocol,
  type SupabaseOpError,
  type SupabaseOpContext,
} from "./protocol.ts";
export * as Retry from "./retry.ts";
// Flat operation surface (v0 parity: every v1* op at the package root).
export * from "./services/supabase.ts";
